from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    foreground = next(value for value in Counter(value for row in grid for value in row) if value != background)
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == foreground and row[c + 1] == foreground:
                out[r][c] = 2
    return out
